import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const s="/assets/pipeline.D5yahtFl.svg",u=JSON.parse('{"title":"How ripeat works","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),n={name:"architecture.md"};function i(d,e,l,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="how-ripeat-works" tabindex="-1">How ripeat works <a class="header-anchor" href="#how-ripeat-works" aria-label="Permalink to &quot;How ripeat works&quot;">​</a></h1><p>This page is the map of the whole application: the pieces, what happens when you run a command, where files live, and who gets to say yes. Each piece links to the page that covers it in detail.</p><h2 id="the-idea-in-one-paragraph" tabindex="-1">The idea in one paragraph <a class="header-anchor" href="#the-idea-in-one-paragraph" aria-label="Permalink to &quot;The idea in one paragraph&quot;">​</a></h2><p>You keep a <strong>list</strong> of tools you want. ripeat looks each name up in its <strong>recipes</strong> (the &quot;how&quot; for each system), turns the list into an ordered <strong>plan</strong>, <strong>rates the risk</strong> of that plan with plain rules, shows you both, and asks. Only then does it change the machine, writing a <strong>journal</strong> first, so any run can be <strong>undone</strong>. Nothing in that chain is an AI&#39;s guess: the plan, the rating and the lookups are fixed rules, so the same input gives the same answer. An AI assistant can be connected, but it only ever prepares and explains; you stay the one who says yes.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><p><img src="'+s+'" alt="The ripeat pipeline: profile, recipes, plan, engine, with the risk rating, administrator policy, backends and the journal beneath them"></p><p>Every command is some part of this line. <code>plan</code> and <code>assess</code> stop before the engine; <code>install</code> goes all the way; <code>rollback</code> reads the journal backwards.</p><h2 id="the-pieces" tabindex="-1">The pieces <a class="header-anchor" href="#the-pieces" aria-label="Permalink to &quot;The pieces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>What it is</th><th>Read more</th></tr></thead><tbody><tr><td><strong>Profile</strong></td><td>The list of tools you want: <code>ripeat.yaml</code>, or a saved one by name. Says <em>what</em>, never <em>how</em></td><td><a href="./profiles">Profiles: your list</a></td></tr><tr><td><strong>Recipe</strong></td><td>How one tool is installed on each OS: a package manager, a checked download, a vendor installer. Several options per OS, first usable wins</td><td><a href="./recipes">Recipes</a></td></tr><tr><td><strong>Recipe layers</strong></td><td>Built-in recipes, then recipes from added <strong>packs</strong>, then your own. A higher layer wins, and a pack can never replace a built-in one</td><td><a href="./taps">Recipe packs (taps)</a></td></tr><tr><td><strong>Plan</strong></td><td>The recipes resolved for this machine: dependencies first, the method chosen, what is already there</td><td><a href="./install-and-rollback">Install, uninstall, rollback</a></td></tr><tr><td><strong>Risk rating</strong></td><td>LOW, MEDIUM, HIGH or BLOCKED from plain rules (admin rights, a download, a shell command, whether you wrote the recipe). Written reasons, no AI</td><td><a href="./assess">Risk and <code>assess</code></a></td></tr><tr><td><strong>Backends</strong></td><td>One adapter per way of installing: <code>apt</code>, <code>dnf</code>, <code>pacman</code>, <code>snap</code>, <code>flatpak</code>, <code>brew</code>, <code>winget</code>, <code>scoop</code>, <code>choco</code>, downloads, installers. The only code that touches the system</td><td><a href="./recipes">Recipes</a></td></tr><tr><td><strong>Engine</strong></td><td>Runs a plan: asks, takes the lock, journals, installs step by step, undoes a failed run</td><td><a href="./install-and-rollback">Install, uninstall, rollback</a></td></tr><tr><td><strong>State and journal</strong></td><td>What ripeat installed, and a record of every run, written <em>before</em> acting</td><td><a href="./install-and-rollback">Install, uninstall, rollback</a></td></tr><tr><td><strong>Lockfile</strong></td><td><code>ripeat.lock</code>: the exact versions installed, to reproduce them</td><td><a href="./lockfile">The lockfile</a></td></tr><tr><td><strong>Administrator policy</strong></td><td>A file only an administrator can write, that limits methods, download hosts, tools and more, whatever anyone asks</td><td><a href="./admin-policy">Administrator policy</a></td></tr><tr><td><strong>Account policy</strong></td><td>Users, groups and admin rights as a file, applied only when you say so</td><td><a href="./policy">Users and groups</a></td></tr><tr><td><strong>Lookups</strong></td><td><code>find</code> and <code>add</code>: where a tool can come from (package managers, GitHub), drafted into an ordinary recipe you approve</td><td><a href="./find-and-add">Install by name</a></td></tr><tr><td><strong>MCP server</strong></td><td><code>ripeat mcp</code>: lets an AI assistant look things up, plan, rate and prepare drafts. Plan-only by default</td><td><a href="./mcp">ripeat as an MCP server</a>, <a href="./drafts">Drafts from an assistant</a></td></tr></tbody></table><h2 id="what-ripeat-install-git-node-does" tabindex="-1">What <code>ripeat install git node</code> does <a class="header-anchor" href="#what-ripeat-install-git-node-does" aria-label="Permalink to &quot;What `ripeat install git node` does&quot;">​</a></h2><ol><li><strong>Loads the recipes</strong> (built-in, packs, yours) and the <strong>administrator policy</strong>. A policy that exists but cannot be read stops the run: it never fails open.</li><li><strong>Resolves the plan.</strong> Dependencies come first (<code>typescript</code> needs <code>node</code>). For each tool, the first install option that suits this machine and this policy is chosen. A name with no recipe, at a keyboard, is looked up and offered to you to add.</li><li><strong>Applies <code>ripeat.lock</code></strong> if there is one, and runs the <strong>pre-flight checks</strong> (is the method available, does the policy allow it).</li><li><strong>Shows the plan and the risk</strong>, with the reasons. <code>plan</code> and <code>--dry-run</code> stop here.</li><li><strong>Asks.</strong> A HIGH-risk plan needs its own explicit yes. Then, if a step needs administrator rights, it asks for them <strong>once, up front</strong>.</li><li><strong>Takes the lock and writes the journal entry</strong> for the run before anything changes.</li><li><strong>Runs each step.</strong> A tool ripeat already manages is skipped; a tool already on the machine is recorded and <strong>left alone</strong>; anything else is installed through its backend and recorded as it goes.</li><li><strong>If a step fails,</strong> ripeat says why it probably failed and undoes the whole run, newest step first. <strong>If a step needs a restart,</strong> the run pauses and <code>ripeat resume</code> carries on.</li><li><strong>Finishes</strong> with the run marked complete. <code>ripeat rollback</code> can undo it later.</li></ol><h2 id="where-ripeat-keeps-its-files" tabindex="-1">Where ripeat keeps its files <a class="header-anchor" href="#where-ripeat-keeps-its-files" aria-label="Permalink to &quot;Where ripeat keeps its files&quot;">​</a></h2><p>Everything is under one folder, <code>$RIPEAT_HOME</code> (default: <code>~/Library/Application Support/ripeat</code> on macOS, <code>~/.config/ripeat</code> on Linux, <code>%AppData%\\ripeat</code> on Windows). Your lists and policy files (<code>ripeat.yaml</code>, <code>ripeat.lock</code>, <code>ripeat.policy.yaml</code>) live in the folder you run ripeat from. The full table is in <a href="./getting-started">Getting started</a>. The administrator policy lives in a system folder only an administrator can write (<a href="./admin-policy">Administrator policy</a>).</p><h2 id="who-says-yes" tabindex="-1">Who says yes <a class="header-anchor" href="#who-says-yes" aria-label="Permalink to &quot;Who says yes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Who answers</th></tr></thead><tbody><tr><td>Install, uninstall, upgrade, rollback</td><td>You, at a question (<code>--yes</code> answers it, for scripts)</td></tr><tr><td>A HIGH-risk plan</td><td>You, separately (<code>--yes</code> does <strong>not</strong> cover it; <code>--accept-risk</code> does)</td></tr><tr><td>Save a recipe found by <code>find</code> or <code>add</code></td><td>You, after reading it</td></tr><tr><td>Add or update a recipe pack</td><td>You, at a terminal. There is no <code>--yes</code></td></tr><tr><td>Approve a recipe an assistant prepared</td><td>You, at a terminal. There is no <code>--yes</code></td></tr><tr><td>Let an assistant install (<code>--allow-run</code>)</td><td>You turn it on; then you confirm every run in your own app</td></tr><tr><td>What may never happen on this machine</td><td>The administrator&#39;s policy, which nothing overrides</td></tr></tbody></table><h2 id="the-guarantees" tabindex="-1">The guarantees <a class="header-anchor" href="#the-guarantees" aria-label="Permalink to &quot;The guarantees&quot;">​</a></h2><ul><li><strong>Nothing changes without a plan you saw and a yes you gave.</strong> Looking is free: <code>plan</code>, <code>assess</code>, <code>find</code>, <code>list</code>, <code>validate</code> and <code>recipes check</code> change nothing.</li><li><strong>ripeat never removes what it did not install.</strong> A tool that was on the machine first is recorded as such, and left alone by <code>uninstall</code> and <code>rollback</code>.</li><li><strong>Every run is journaled before it acts,</strong> so a crash or a failure can be undone from the journal.</li><li><strong>One writer at a time.</strong> A second ripeat that would change things stops at once and says so.</li><li><strong>Downloads are verified.</strong> A downloaded program or installer must match a SHA-256, and a vendor installer must also carry a valid vendor signature.</li><li><strong>No model decides anything.</strong> Plans, ratings, lookups and drafts come from fixed rules; an AI assistant only asks for them and explains them.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Start with <a href="./getting-started">Getting started</a> and <a href="./profiles">Profiles: your list</a>.</li><li>To understand a plan before you run it: <a href="./assess">Risk and <code>assess</code></a> and <a href="./install-and-rollback">Install, uninstall, rollback</a>.</li><li>To use it from an AI assistant: <a href="./mcp">ripeat as an MCP server</a>.</li><li>To use it across a team: <a href="./taps">Recipe packs (taps)</a>, <a href="./admin-policy">Administrator policy</a> and <a href="./privileges">Admin rights</a>.</li><li>To see what has been tested on which system: <a href="./platforms">What has been verified</a>.</li></ul>',19)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
